"""Extract the config resource-type taxonomy and secret field paths (21-01).

Usage: python3 -I extract_openapi.py OPENAPI_JSON OUT_JSON

OPENAPI_JSON is the live Ignition 8.3.6 OpenAPI document fetched from the
ign-deploy-rig rig (kept outside the repo, ~/.cache/ign-deploy-rig/openapi-8.3.6.json).
OUT_JSON is written with sorted keys, two-space indent and a trailing newline
(this is ign's own file, not a gateway file, so sorted keys are correct).

Output keys:
  source          fixed provenance string
  types           [{module, type, named}] sorted by module then type.
                  named is true when the gateway exposes a per-name route for
                  the pair (a path segment `{name}` after module and type, as in
                  `/resources/{module}/{type}/{name}/{signature}` or the verb
                  routes `find/{module}/{type}/{name}`); singletons only carry
                  `/{signature}`. Verb and sub-tree prefixes (find, list, names,
                  singleton, delete, rename, type, datafile, copy, move) are
                  never read as module names.
  secret_fields   [{module, type, paths}] for every type whose create or update
                  request body has a property whose schema is a oneOf/anyOf that
                  holds both the Embedded and the Referenced secret schema. paths
                  are dotted property paths relative to the resource `config`
                  object, with oneOf/anyOf/allOf/items segments stripped.

Prints counts only.
"""

import json
import sys

PREFIX = "/data/api/v1/resources/"
# First path segments under /resources/ that are verbs or sub-trees, never module
# names. Each verb route repeats `{module}/{type}` after the verb.
VERBS = {
    "find", "list", "names", "singleton", "delete", "rename", "type", "datafile",
    "copy", "move",
}
SOURCE = (
    "Ignition 8.3.6 OpenAPI from the ign-deploy-rig live rig, "
    "generated by tests/fixtures/deploy/extract_openapi.py"
)


def is_template(segment):
    return segment.startswith("{") and segment.endswith("}")


def collect_types(paths):
    """Return {(module, type): named} over every route that names the pair.

    The canonical routes are `/resources/{module}/{type}[/...]`; the verb
    routes (find, list, names, singleton, delete, rename, type, datafile) put
    the verb first and then `{module}/{type}`. A pair is named when any of its
    routes carries a `{name}` segment after the type.
    """
    types = {}
    for path in paths:
        if not path.startswith(PREFIX):
            continue
        segs = path[len(PREFIX):].split("/")
        if segs[0] in VERBS:
            segs = segs[1:]
        if len(segs) < 2 or is_template(segs[0]) or is_template(segs[1]):
            continue
        key = (segs[0], segs[1])
        named = any(s == "{name}" for s in segs[2:])
        types[key] = types.get(key, False) or named
    return types


def resolve(schema, root, seen):
    """Follow $ref chains; returns (schema, seen, ok). ok is False on a cycle."""
    while isinstance(schema, dict) and "$ref" in schema:
        ref = schema["$ref"]
        if ref in seen:
            return None, seen, False
        seen = seen | {ref}
        node = root
        for part in ref.lstrip("#/").split("/"):
            node = node[part.replace("~1", "/").replace("~0", "~")]
        schema = node
    return schema, seen, True


def const_of(schema):
    props = schema.get("properties") if isinstance(schema, dict) else None
    type_prop = props.get("type") if isinstance(props, dict) else None
    return type_prop.get("const") if isinstance(type_prop, dict) else None


def is_secret(schema):
    for key in ("oneOf", "anyOf"):
        variants = schema.get(key)
        if isinstance(variants, list):
            consts = {const_of(v) for v in variants if isinstance(v, dict)}
            if "Embedded" in consts and "Referenced" in consts:
                return True
    return False


def walk(schema, root, trail, seen, found):
    schema, seen, ok = resolve(schema, root, seen)
    if not ok or not isinstance(schema, dict):
        return
    if trail and is_secret(schema):
        found.add(".".join(trail))
        return
    for name, sub in (schema.get("properties") or {}).items():
        walk(sub, root, trail + [name], seen, found)
    if "items" in schema:
        walk(schema["items"], root, trail, seen, found)
    for key in ("oneOf", "anyOf", "allOf"):
        for sub in schema.get(key) or []:
            walk(sub, root, trail, seen, found)


def body_schema(operation):
    body = operation.get("requestBody") or {}
    return ((body.get("content") or {}).get("application/json") or {}).get("schema")


def collect_secrets(paths, root, types):
    out = {}
    for module, typ in types:
        route = PREFIX + module + "/" + typ
        found = set()
        for method in ("post", "put"):
            schema = body_schema((paths.get(route) or {}).get(method) or {})
            if schema is None:
                continue
            resolved, _, ok = resolve(schema, root, frozenset())
            items = resolved.get("items") if ok and isinstance(resolved, dict) else None
            config = ((items or {}).get("properties") or {}).get("config")
            if config is not None:
                walk(config, root, [], frozenset(), found)
        if found:
            out[(module, typ)] = sorted(found)
    return out


def main(argv):
    if len(argv) != 3:
        print("usage: extract_openapi.py OPENAPI_JSON OUT_JSON", file=sys.stderr)
        return 2
    with open(argv[1], encoding="utf-8") as fh:
        root = json.load(fh)
    paths = root["paths"]
    types = collect_types(paths)
    secrets = collect_secrets(paths, root, types)
    result = {
        "source": SOURCE,
        "types": [
            {"module": m, "type": t, "named": types[(m, t)]} for m, t in sorted(types)
        ],
        "secret_fields": [
            {"module": m, "type": t, "paths": secrets[(m, t)]} for m, t in sorted(secrets)
        ],
    }
    with open(argv[2], "w", encoding="utf-8", newline="\n") as fh:
        fh.write(json.dumps(result, indent=2, sort_keys=True) + "\n")
    named = sum(1 for v in types.values() if v)
    print(f"types {len(types)}")
    print(f"named {named}")
    print(f"singleton {len(types) - named}")
    print(f"secret types {len(secrets)}")
    print(f"secret paths {sum(len(v) for v in secrets.values())}")
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))
